import heapq

def match(orders):
    trades = []
    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    book = {}       # id -> {'side':..., 'price':..., 'qty':..., 'active':bool}
    seq_counter = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        seq = seq_counter
        seq_counter += 1

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                sinfo = book.get(sid)
                if sinfo is None or not sinfo['active'] or sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and sp > price:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] == 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)

            if typ == 'limit':
                if remaining > 0:
                    book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    book[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'active': False}
            # ioc/market: remainder discarded, nothing to store

        else:  # side == 'sell'
            while remaining > 0 and buy_heap:
                bp_neg, bseq, bid = buy_heap[0]
                bp = -bp_neg
                binfo = book.get(bid)
                if binfo is None or not binfo['active'] or binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and bp < price:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] == 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)

            if typ == 'limit':
                if remaining > 0:
                    book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                    heapq.heappush(sell_heap, (price, seq, oid))
                else:
                    book[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'active': False}
            # ioc/market: remainder discarded, nothing to store

    return trades

